-- Puzzles (Plus). Tactics from the lichess puzzle database (CC0, database.lichess.org); the selection is
-- generated by scripts/build-puzzles.mjs into a later migration. Every player has a puzzle rating that
-- moves like Elo; the next puzzle is picked near that rating and never repeats.
--
-- Puzzle format (as in the lichess database): `fen` is the position BEFORE the opponent's move,
-- `moves[1]` is that opponent move, then the solution alternates player / opponent in UCI.

create table public.puzzles (
  id         text primary key,
  fen        text not null,
  moves      text[] not null check (cardinality(moves) >= 2),
  rating     int not null,
  popularity int not null default 0,
  themes     text[] not null default '{}'
);
alter table public.puzzles enable row level security;
create index puzzles_rating_idx on public.puzzles(rating);
-- Clients never read the table directly (solutions!); next_puzzle hands out one puzzle at a time.
create policy puzzles_none on public.puzzles for select to anon, authenticated using (false);

create table public.puzzle_stats (
  user_id    uuid primary key references public.profiles(id) on delete cascade,
  rating     int not null default 1200,
  solved     int not null default 0,
  failed     int not null default 0,
  streak     int not null default 0,
  updated_at timestamptz not null default now()
);
alter table public.puzzle_stats enable row level security;
create policy puzzle_stats_select_own on public.puzzle_stats for select to authenticated
  using (user_id = (select auth.uid()));

create table public.puzzle_attempts (
  user_id    uuid not null references public.profiles(id) on delete cascade,
  puzzle_id  text not null references public.puzzles(id) on delete cascade,
  solved     boolean,                 -- null = handed out, not answered yet
  created_at timestamptz not null default now(),
  primary key (user_id, puzzle_id)
);
alter table public.puzzle_attempts enable row level security;
create index puzzle_attempts_puzzle_idx on public.puzzle_attempts(puzzle_id);
create policy puzzle_attempts_select_own on public.puzzle_attempts for select to authenticated
  using (user_id = (select auth.uid()));

-- Free players get this many puzzles per day (0 = Plus only).
create or replace function public.puzzle_free_per_day() returns int language sql immutable set search_path = public as $$ select 0 $$;

-- Returns the player's puzzle rating and counters, plus whether more puzzles are available today.
create or replace function public.puzzle_status()
returns json language plpgsql stable security definer set search_path = public as $$
declare v_me uuid := auth.uid(); s public.puzzle_stats; v_plus boolean; v_today int;
begin
  if v_me is null then raise exception 'not_authenticated'; end if;
  select * into s from public.puzzle_stats where user_id = v_me;
  v_plus := public.effective_plan(v_me) <> 'free';
  select count(*) into v_today from public.puzzle_attempts
    where user_id = v_me and created_at >= date_trunc('day', now() at time zone 'Europe/Berlin') at time zone 'Europe/Berlin';
  return json_build_object(
    'rating', coalesce(s.rating, 1200), 'solved', coalesce(s.solved, 0), 'failed', coalesce(s.failed, 0),
    'streak', coalesce(s.streak, 0), 'plus', v_plus,
    'remaining_today', case when v_plus then null else greatest(0, public.puzzle_free_per_day() - v_today) end);
end;
$$;

-- Hands out the next puzzle near the player's rating (one they have never seen). An unanswered puzzle
-- from before is handed out again, so reloading does not skip puzzles.
create or replace function public.next_puzzle()
returns json language plpgsql security definer set search_path = public as $$
declare
  v_me uuid := auth.uid();
  v_rating int;
  v_today int;
  p public.puzzles;
  v_width int := 100;
begin
  if v_me is null then raise exception 'not_authenticated'; end if;
  select pz.* into p from public.puzzle_attempts a join public.puzzles pz on pz.id = a.puzzle_id
    where a.user_id = v_me and a.solved is null order by a.created_at desc limit 1;
  if p.id is null then
    if public.effective_plan(v_me) = 'free' then
      select count(*) into v_today from public.puzzle_attempts
        where user_id = v_me and created_at >= date_trunc('day', now() at time zone 'Europe/Berlin') at time zone 'Europe/Berlin';
      if v_today >= public.puzzle_free_per_day() then raise exception 'puzzle_requires_plus'; end if;
    end if;
    select coalesce((select rating from public.puzzle_stats where user_id = v_me), 1200) into v_rating;
    while p.id is null and v_width <= 3200 loop
      select pz.* into p from public.puzzles pz
        where pz.rating between v_rating - v_width and v_rating + v_width
          and not exists (select 1 from public.puzzle_attempts a where a.user_id = v_me and a.puzzle_id = pz.id)
        order by random() limit 1;
      v_width := v_width * 2;
    end loop;
    if p.id is null then raise exception 'no_puzzles_left'; end if;
    insert into public.puzzle_attempts (user_id, puzzle_id) values (v_me, p.id);
  end if;
  return json_build_object('id', p.id, 'fen', p.fen, 'moves', p.moves, 'rating', p.rating, 'themes', p.themes);
end;
$$;

-- Records the result of a handed-out puzzle and moves the rating (Elo; K = 40 for the first 20 puzzles,
-- then 20). Answering the same puzzle twice changes nothing.
create or replace function public.submit_puzzle(p_puzzle text, p_solved boolean)
returns json language plpgsql security definer set search_path = public as $$
declare
  v_me uuid := auth.uid();
  v_prating int;
  s public.puzzle_stats;
  v_expected float8;
  v_k int;
  v_delta int;
begin
  if v_me is null then raise exception 'not_authenticated'; end if;
  update public.puzzle_attempts set solved = p_solved
    where user_id = v_me and puzzle_id = p_puzzle and solved is null;
  if not found then raise exception 'puzzle_not_open'; end if;
  select rating into v_prating from public.puzzles where id = p_puzzle;
  insert into public.puzzle_stats (user_id) values (v_me) on conflict (user_id) do nothing;
  select * into s from public.puzzle_stats where user_id = v_me for update;
  v_expected := 1 / (1 + power(10, (v_prating - s.rating) / 400.0));
  v_k := case when s.solved + s.failed < 20 then 40 else 20 end;
  v_delta := round(v_k * ((case when p_solved then 1 else 0 end) - v_expected));
  update public.puzzle_stats set
    rating = greatest(400, s.rating + v_delta),
    solved = s.solved + case when p_solved then 1 else 0 end,
    failed = s.failed + case when p_solved then 0 else 1 end,
    streak = case when p_solved then s.streak + 1 else 0 end,
    updated_at = now()
    where user_id = v_me;
  return json_build_object('rating', greatest(400, s.rating + v_delta), 'delta', v_delta);
end;
$$;

revoke execute on function public.puzzle_status() from public, anon;
revoke execute on function public.next_puzzle() from public, anon;
revoke execute on function public.submit_puzzle(text, boolean) from public, anon;
grant execute on function public.puzzle_status() to authenticated;
grant execute on function public.next_puzzle() to authenticated;
grant execute on function public.submit_puzzle(text, boolean) to authenticated;
